      "type": "object",
      "properties": {
        "itemType": {
          "type": [
            "string",
            "null"
          ],
          "default": null
        },
        "status": {
          "type": [
            "string",
            "null"
          ],
          "default": null
        },
        "query": {
          "type": [
            "string",
            "null"
          ],
          "default": null
        },
        "includeSuperseded": {
          "type": "boolean",
