                  "null"
                ]
              },
              "newStatement": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "reason": {
                "type": [
                  "string",
                  "null"
                ]
              }
            },
            "required": [
              "decisionId",
              "action",
              "outcome",
              "newStatement",
              "reason"
            ]
          }
